<?php if($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-5"><div class="soft-card p-4"><h5 class="fw-bold mb-3">Status Hari Ini</h5><p>Status: <span class="badge <?= ($session['status'] ?? '')==='open'?'bg-success':'bg-secondary' ?>"><?= strtoupper($session['status'] ?? 'CLOSED') ?></span></p><?php if($session): ?><p class="mb-1">Tanggal: <strong><?= htmlspecialchars($session['business_date']) ?></strong></p><p class="mb-1">Opening Cash: <strong><?= rupiah($session['opening_cash']) ?></strong></p><p class="mb-0">Dibuka: <strong><?= htmlspecialchars($session['opened_at']) ?></strong></p><?php endif; ?></div></div><div class="col-lg-7"><div class="soft-card p-4"><?php if(($session['status'] ?? '')==='open'): ?><h5 class="fw-bold mb-3">Tutup Toko</h5><form method="post" action="<?= url('/store/close') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Kas Fisik di Laci</label><input type="number" step="0.01" name="physical_cash" class="form-control" required></div><div class="mb-3"><label class="form-label">Catatan Closing</label><textarea name="notes" class="form-control" rows="3"></textarea></div><button class="btn btn-danger" data-confirm="Yakin tutup toko hari ini?">Tutup Toko</button></form><?php else: ?><h5 class="fw-bold mb-3">Buka Toko</h5><form method="post" action="<?= url('/store/open') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Modal Kas Awal</label><input type="number" step="0.01" name="opening_cash" class="form-control" value="0" required></div><label class="form-label">Staf Bertugas</label><div class="row"><?php foreach($staff as $u): ?><div class="col-md-6"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="staff_ids[]" value="<?= $u['id'] ?>"> <span class="form-check-label"><?= htmlspecialchars($u['name']) ?> <small class="text-muted">(<?= rupiah($u['daily_salary']) ?>)</small></span></label></div><?php endforeach; ?></div><button class="btn btn-sim mt-3">Buka Toko</button></form><?php endif; ?></div></div></div>
